// ---- /order-confirmed ----
// Reads ?session_id= from the Stripe redirect and looks up the matching order
function OrderConfirmed() {
  const [order, setOrder] = useState(null);
  const [status, setStatus] = useState("loading"); // loading | found | not_found

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const sessionId = params.get("session_id");
    if (!sessionId) {
      setStatus("not_found");
      return;
    }

    fetch(
      `${SUPABASE_URL}/rest/v1/orders?stripe_checkout_session_id=eq.${sessionId}&select=id,total_cents,status,order_items(product_name,quantity)`,
      {
        headers: {
          apikey: SUPABASE_ANON_KEY,
          Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
        },
      }
    )
      .then((res) => res.json())
      .then((data) => {
        if (data?.[0]) {
          setOrder(data[0]);
          setStatus("found");
        } else {
          setStatus("not_found");
        }
      })
      .catch(() => setStatus("not_found"));
  }, []);

  return (
    <Shell>
      {status === "loading" && (
        <p className="text-sm text-stone-500">Confirming your order…</p>
      )}

      {status === "not_found" && (
        <>
          <CheckCircle2 className="w-12 h-12 text-emerald-700 mb-4" strokeWidth={1.5} />
          <h1 className="font-serif text-2xl text-emerald-950 mb-2">
            Thank you for your order
          </h1>
          <p className="text-sm text-stone-600 max-w-sm">
            A confirmation email is on its way. If anything looks off, contact
            us at hello@fofodeluxe.com.
          </p>
        </>
      )}

      {status === "found" && order && (
        <>
          <CheckCircle2 className="w-12 h-12 text-emerald-700 mb-4" strokeWidth={1.5} />
          <h1 className="font-serif text-2xl text-emerald-950 mb-2">
            Order confirmed
          </h1>
          <p className="text-sm text-stone-600 mb-6">
            We've received your payment and we're getting your order ready.
          </p>
          <div className="bg-white rounded-2xl border border-emerald-900/10 p-5 text-left w-full max-w-sm">
            {order.order_items?.map((item, i) => (
              <div key={i} className="flex justify-between text-sm py-1.5">
                <span className="text-stone-700">
                  {item.quantity} × {item.product_name}
                </span>
              </div>
            ))}
            <div className="border-t border-emerald-900/10 mt-3 pt-3 flex justify-between font-mono text-sm">
              <span>Total</span>
              <span>£{(order.total_cents / 100).toFixed(2)}</span>
            </div>
          </div>
          <a
            href="/"
            className="mt-8 inline-flex px-6 py-3 rounded-full bg-emerald-950 text-stone-50 text-sm font-medium hover:bg-emerald-900 transition-colors"
          >
            Continue shopping
          </a>
        </>
      )}
    </Shell>
  );
}

